/*
 * Project      : VLSI Technology - AI RTL generator
 * Author       : Nguyen Quan and Claude (user)
 * AI Flow      : VLSIT RTL Generator AI Automation Flow
 * AI Flow Page : https://github.com/nguyenquanicd/VLSIT_RTL_Generator_AI_Model
 * Date         : 2026-10-18
 * Module       : m_apb_if
 * Purpose      : APB4 completer side of the APB to TL-UL bridge. It detects the Setup phase,
 *                checks the request, launches it to the TL-UL side and returns the completion.
 * Spec sections: 5.1 (internal interface), 5.3 (early launch and back-to-back transfers),
 *                5.4 (invariants), 6.3 (APB transfer cases), 7.3 (reset), 10.1 (APB FSM),
 *                12 (local errors), 14.2 (hierarchy: APB-facing logic).
 */
`timescale 1ns/1ps

module m_apb_if #(
  // Parameter Description: width of the APB byte address; bits [1:0] are checked for alignment.
  // Parameter values: legal range is 16 to 32; default is 32.
  // Parameter unit: bit
  parameter logic [31:0] PARA_ADDR_W = 32
) (
  input wire i_clk_core,
  input wire i_rst_n_core,
  input wire i_apb_psel,
  input wire i_apb_penable,
  input wire i_apb_pwrite,
  input wire i_resp_valid,
  input wire i_resp_err,
  input wire [PARA_ADDR_W-1:0] i_apb_paddr,
  input wire [3:0] i_apb_pstrb,
  input wire [31:0] i_apb_pwdata,
  input wire [31:0] i_resp_rdata,
  output logic o_req_launch,
  output logic o_req_wr,
  output logic o_apb_pready,
  output logic o_apb_pslverr,
  output logic [PARA_ADDR_W-3:0] o_req_addr,
  output logic [31:0] o_req_wdata,
  output logic [31:0] o_apb_prdata
);

  // APB FSM states: IDLE waits for a Setup phase, BUSY waits for the TL-UL response, and DONE
  // holds PREADY for one cycle. Unused encoding 2'b11 recovers to ENUM_ST_IDLE.
  typedef enum logic [1:0] {
    ENUM_ST_IDLE = 2'b00,
    ENUM_ST_BUSY = 2'b01,
    ENUM_ST_DONE = 2'b10
  } apb_state_type_def;

  // Internal signal declarations
  apb_state_type_def reg_fsm_apb_current_state;
  apb_state_type_def w_fsm_apb_nxt_state;
  logic w_setup;
  logic w_legal;
  logic w_req_launch;
  logic w_local_err;
  logic w_pready_nxt;
  logic w_pslverr_nxt;
  logic [31:0] w_prdata_nxt;
  logic reg_pready;
  logic reg_pslverr;
  logic [31:0] reg_prdata;

  // Setup phase: the level PSEL = 1 with PENABLE = 0 while the FSM is idle, not an edge of PSEL, so
  // back-to-back transfers with PSEL held high start exactly like the first transfer.
  // REQ: BR-3-01, BR-3-12, BR-5.3-10, BR-1.3-05, BR-20-12
  assign w_setup = (reg_fsm_apb_current_state == ENUM_ST_IDLE) & i_apb_psel & ~i_apb_penable;

  // Legal request: word-aligned address, and a full strobe when the access is a write.
  // PSTRB is ignored on reads, where the APB requester drives it LOW.
  // REQ: BR-T1-03, BR-T1-04, BR-2.3-01, BR-2.3-02, BR-3-05, BR-6.3-04, BR-9-04
  assign w_legal = (i_apb_paddr[1:0] == 2'b00) & (~i_apb_pwrite | (i_apb_pstrb == 4'b1111));

  // A legal Setup phase launches the TL-UL request; an illegal one gets a local error answer.
  // REQ: BR-5.1-02, BR-T1-05, BR-5.4-05, BR-1.3-03
  assign w_req_launch = w_setup & w_legal;
  assign w_local_err  = w_setup & ~w_legal;

  // Request bundle for the TL-UL side: forwarded straight from the APB inputs of the Setup cycle.
  // REQ: BR-5.1-02, BR-5.3-01
  assign o_req_launch = w_req_launch;
  assign o_req_wr     = i_apb_pwrite;
  assign o_req_addr   = i_apb_paddr[PARA_ADDR_W-1:2];
  assign o_req_wdata  = i_apb_pwdata;

  // Completion outputs come straight from flip-flops.
  // REQ: BR-3-17, BR-5.3-07, BR-20-08
  assign o_apb_pready  = reg_pready;
  assign o_apb_pslverr = reg_pslverr;
  assign o_apb_prdata  = reg_prdata;

  // Next-state logic: IDLE moves to BUSY on a launch or to DONE on a local error, BUSY moves to
  // DONE when the response arrives, and DONE always returns to IDLE. The next state gets its
  // default first and the case has a default branch, so no latch is inferred.
  // REQ: BR-10.1-01, BR-10.1-02, BR-10.1-03, BR-5.3-11, BR-5.4-04
  always_comb begin : p_com_fsm_nxt
    w_fsm_apb_nxt_state = reg_fsm_apb_current_state;
    case (reg_fsm_apb_current_state)
      ENUM_ST_IDLE: begin
        if (w_req_launch) begin
          w_fsm_apb_nxt_state = ENUM_ST_BUSY;
        end else if (w_local_err) begin
          w_fsm_apb_nxt_state = ENUM_ST_DONE;
        end
      end
      ENUM_ST_BUSY: begin
        if (i_resp_valid) begin
          w_fsm_apb_nxt_state = ENUM_ST_DONE;
        end
      end
      ENUM_ST_DONE: w_fsm_apb_nxt_state = ENUM_ST_IDLE;
      default:      w_fsm_apb_nxt_state = ENUM_ST_IDLE;
    endcase
  end

  // Completion values: PREADY and PSLVERR last one cycle. A local error clears PRDATA, a response
  // loads PRDATA (already zero for writes and errors), otherwise PRDATA holds its last value.
  // Every next value gets its default first, so no latch is inferred.
  // REQ: BR-3-24, BR-3-25, BR-12-01, BR-12-04, BR-3-09, BR-3-10, BR-3-18, BR-3-19, BR-6.2-04
  always_comb begin : p_com_resp
    w_pready_nxt  = 1'b0;
    w_pslverr_nxt = 1'b0;
    w_prdata_nxt  = reg_prdata;
    if (w_local_err) begin
      w_pready_nxt  = 1'b1;
      w_pslverr_nxt = 1'b1;
      w_prdata_nxt  = '0;
    end else if ((reg_fsm_apb_current_state == ENUM_ST_BUSY) & i_resp_valid) begin
      w_pready_nxt  = 1'b1;
      w_pslverr_nxt = i_resp_err;
      w_prdata_nxt  = i_resp_rdata;
    end
  end

  // Current-state register: the control state is reset asynchronously to IDLE and otherwise takes
  // the next state every clock cycle.
  // REQ: BR-3-30, BR-7.3-02, BR-3-32
  always_ff @(posedge i_clk_core, negedge i_rst_n_core) begin : p_ff_fsm_apb
    if (!i_rst_n_core) begin
      reg_fsm_apb_current_state <= ENUM_ST_IDLE;
    end else begin
      reg_fsm_apb_current_state <= w_fsm_apb_nxt_state;
    end
  end

  // Completion flip-flops: all are reset asynchronously to zero, so every output is defined
  // after reset.
  // REQ: BR-3-31, BR-7.3-02, BR-6.2-03, BR-5.3-06
  always_ff @(posedge i_clk_core, negedge i_rst_n_core) begin : p_ff_resp
    if (!i_rst_n_core) begin
      reg_pready  <= 1'b0;
      reg_pslverr <= 1'b0;
      reg_prdata  <= '0;
    end else begin
      reg_pready  <= w_pready_nxt;
      reg_pslverr <= w_pslverr_nxt;
      reg_prdata  <= w_prdata_nxt;
    end
  end

endmodule

/*
 * Project      : VLSI Technology - AI RTL generator
 * Author       : Nguyen Quan and Claude (user)
 * AI Flow      : VLSIT RTL Generator AI Automation Flow
 * AI Flow Page : https://github.com/nguyenquanicd/VLSIT_RTL_Generator_AI_Model
 * Date         : 2026-10-18
 * Module       : m_tlul_if
 * Purpose      : TL-UL host side of the APB to TL-UL bridge. Loads channel A from flip-flops at
 *                the launch edge, holds it until accepted, accepts the response and checks it.
 * Spec sections: 5.1 (internal interface), 5.3 (early launch), 5.4 (invariants),
 *                6.2 (TL-UL ports), 6.3 (TL-UL transfer cases), 7.3 (reset), 8 (parameters),
 *                9 (address, opcode and response mapping), 10.1 (TL-UL FSM),
 *                14.2 (hierarchy: TL-UL-facing logic).
 */
`timescale 1ns/1ps

module m_tlul_if #(
  // Parameter Description: width of the channel A byte address; its two low bits are always zero.
  // Parameter values: legal range is 16 to 32; default is 32.
  // Parameter unit: bit
  parameter logic [31:0] PARA_ADDR_W = 32,
  // Parameter Description: width of the TL-UL source identifier on channels A and D.
  // Parameter values: legal range is 1 to 8; default is 8.
  // Parameter unit: bit
  parameter logic [31:0] PARA_SRC_W = 8,
  // Parameter Description: constant source identifier of every request; it fits PARA_SRC_W bits.
  // Parameter values: 0 to 2^PARA_SRC_W - 1; default is 0.
  // Parameter unit: none
  parameter logic [31:0] PARA_SRC_ID = 0,
  // Parameter Description: width of the a_user bits, which are always driven to zero.
  // Parameter values: legal range is 1 to 32; default is 1.
  // Parameter unit: bit
  parameter logic [31:0] PARA_A_USER_W = 1
) (
  input wire i_clk_core,
  input wire i_rst_n_core,
  input wire i_req_launch,
  input wire i_req_wr,
  input wire i_tlul_a_ready,
  input wire i_tlul_d_valid,
  input wire i_tlul_d_error,
  input wire [PARA_ADDR_W-3:0] i_req_addr,
  input wire [31:0] i_req_wdata,
  input wire [2:0] i_tlul_d_opcode,
  input wire [PARA_SRC_W-1:0] i_tlul_d_source,
  input wire [31:0] i_tlul_d_data,
  output logic o_resp_valid,
  output logic o_resp_err,
  output logic o_tlul_a_valid,
  output logic o_tlul_d_ready,
  output logic [31:0] o_resp_rdata,
  output logic [2:0] o_tlul_a_opcode,
  output logic [2:0] o_tlul_a_param,
  output logic [1:0] o_tlul_a_size,
  output logic [PARA_SRC_W-1:0] o_tlul_a_source,
  output logic [PARA_ADDR_W-1:0] o_tlul_a_address,
  output logic [3:0] o_tlul_a_mask,
  output logic [31:0] o_tlul_a_data,
  output logic [PARA_A_USER_W-1:0] o_tlul_a_user
);

  // Fixed, non-overridable constants of the TL-UL host.
  // REQ: BR-8-08
  // Request size code 2 means a 4-byte access (a_size = 2'b10).
  localparam logic [1:0] LPARA_A_SIZE = 2'd2;
  // Request mask 4'b1111: every byte lane of the 32-bit bus is active.
  localparam logic [3:0] LPARA_A_MASK = 4'b1111;
  // d_opcode of AccessAckData, the expected response of a Get request.
  localparam logic [2:0] LPARA_D_ACK_DATA = 3'd1;
  // Constant source identifier, PARA_SRC_W bits wide.
  localparam logic [PARA_SRC_W-1:0] LPARA_SRC_ID = PARA_SRC_ID[PARA_SRC_W-1:0];

  // TL-UL FSM states: IDLE has no request outstanding, REQ presents channel A until it is accepted,
  // and WAIT waits for the response. Unused encoding 2'b11 recovers to ENUM_ST_IDLE.
  typedef enum logic [1:0] {
    ENUM_ST_IDLE = 2'b00,
    ENUM_ST_REQ  = 2'b01,
    ENUM_ST_WAIT = 2'b10
  } tlul_state_type_def;

  // Internal signal declarations
  tlul_state_type_def reg_fsm_tlul_current_state;
  tlul_state_type_def w_fsm_tlul_nxt_state;
  logic reg_a_valid;
  logic reg_d_ready;
  logic reg_a_rd;
  logic [PARA_ADDR_W-3:0] reg_a_addr;
  logic [31:0] reg_a_data;
  logic w_load;
  logic w_resp_hit;
  logic w_resp_err;
  logic w_a_valid_nxt;
  logic w_a_rd_nxt;
  logic [PARA_ADDR_W-3:0] w_a_addr_nxt;
  logic [31:0] w_a_data_nxt;
  logic [2:0] w_exp_opcode;

  // Launch: the APB side presents a legal request while no request is outstanding.
  // REQ: BR-3-06, BR-3-07, BR-5.4-01
  assign w_load = i_req_launch & (reg_fsm_tlul_current_state == ENUM_ST_IDLE);

  // A response counts only for an accepted request: in WAIT, or in REQ in the cycle of acceptance.
  // A d_valid at any other time is an orphan response and is discarded.
  // REQ: BR-10.1-05, BR-10.1-06, BR-3-11, BR-6.3-08, BR-6.3-09
  assign w_resp_hit = i_tlul_d_valid & reg_d_ready &
                      (((reg_fsm_tlul_current_state == ENUM_ST_REQ) & i_tlul_a_ready) |
                       (reg_fsm_tlul_current_state == ENUM_ST_WAIT));

  // Response check: a Get expects AccessAckData and a write expects AccessAck; d_source must echo
  // the constant source identifier; d_error is an error response. Any failure gives an error.
  // REQ: BR-3-26, BR-3-27, BR-3-28, BR-1.3-04, BR-9-09, BR-20-10, BR-8-04
  assign w_exp_opcode = reg_a_rd ? LPARA_D_ACK_DATA : 3'b000;
  assign w_resp_err   = i_tlul_d_error | (i_tlul_d_opcode != w_exp_opcode) |
                        (i_tlul_d_source != LPARA_SRC_ID);

  // Response bundle for the APB side: read data only for an error-free read, zero otherwise.
  // REQ: BR-5.1-03, BR-9-10, BR-6.3-14, BR-6.3-15
  assign o_resp_valid = w_resp_hit;
  assign o_resp_err   = w_resp_err;
  assign o_resp_rdata = (reg_a_rd & ~w_resp_err) ? i_tlul_d_data : 32'h0000_0000;

  // Channel A outputs: valid, opcode bit 2 (1 = Get), address and data come from flip-flops.
  // REQ: BR-3-17, BR-9-03, BR-9-05, BR-6.2-07, BR-6.2-11, BR-6.2-13, BR-6.2-15
  assign o_tlul_a_valid   = reg_a_valid;
  assign o_tlul_a_opcode  = {reg_a_rd, 2'b00};
  assign o_tlul_a_address = {reg_a_addr, 2'b00};
  assign o_tlul_a_data    = reg_a_data;
  assign o_tlul_d_ready   = reg_d_ready;

  // Constant channel A fields are tie-offs: they never change, so they need no flip-flop.
  // REQ: BR-3-20, BR-6.2-08, BR-6.2-09, BR-6.2-10, BR-6.2-12, BR-6.2-14, BR-2.3-04, BR-2.3-05
  assign o_tlul_a_param  = 3'b000;
  assign o_tlul_a_size   = LPARA_A_SIZE;
  assign o_tlul_a_mask   = LPARA_A_MASK;
  assign o_tlul_a_source = LPARA_SRC_ID;
  assign o_tlul_a_user   = '0;

  // Next-state logic: IDLE moves to REQ on a launch; REQ leaves when channel A is accepted, going
  // to IDLE if the response arrives in the same cycle and to WAIT otherwise; WAIT leaves on the
  // response. The next state gets its default first and the case has a default branch, so no
  // latch is inferred.
  // REQ: BR-10.1-04, BR-5.3-08, BR-5.4-06
  always_comb begin : p_com_fsm_nxt
    w_fsm_tlul_nxt_state = reg_fsm_tlul_current_state;
    case (reg_fsm_tlul_current_state)
      ENUM_ST_IDLE: begin
        if (w_load) begin
          w_fsm_tlul_nxt_state = ENUM_ST_REQ;
        end
      end
      ENUM_ST_REQ: begin
        if (i_tlul_a_ready) begin
          if (w_resp_hit) begin
            w_fsm_tlul_nxt_state = ENUM_ST_IDLE;
          end else begin
            w_fsm_tlul_nxt_state = ENUM_ST_WAIT;
          end
        end
      end
      ENUM_ST_WAIT: begin
        if (w_resp_hit) begin
          w_fsm_tlul_nxt_state = ENUM_ST_IDLE;
        end
      end
      default: w_fsm_tlul_nxt_state = ENUM_ST_IDLE;
    endcase
  end

  // Channel A control and payload values: the request loads at the launch edge and then holds, so
  // channel A is stable while o_tlul_a_valid is high and i_tlul_a_ready is low. Every next value
  // gets its default first, so no latch is inferred.
  // REQ: BR-5.3-02, BR-3-02, BR-3-03, BR-3-04, BR-3-08, BR-5.4-02, BR-5.4-03
  always_comb begin : p_com_chan_a
    w_a_valid_nxt = (w_fsm_tlul_nxt_state == ENUM_ST_REQ);
    w_a_rd_nxt    = reg_a_rd;
    w_a_addr_nxt  = reg_a_addr;
    w_a_data_nxt  = reg_a_data;
    if (w_load) begin
      w_a_rd_nxt   = ~i_req_wr;
      w_a_addr_nxt = i_req_addr;
      w_a_data_nxt = i_req_wdata;
    end
  end

  // Current-state register: the control state is reset asynchronously to IDLE and otherwise takes
  // the next state every clock cycle.
  // REQ: BR-3-30, BR-7.3-02
  always_ff @(posedge i_clk_core, negedge i_rst_n_core) begin : p_ff_fsm_tlul
    if (!i_rst_n_core) begin
      reg_fsm_tlul_current_state <= ENUM_ST_IDLE;
    end else begin
      reg_fsm_tlul_current_state <= w_fsm_tlul_nxt_state;
    end
  end

  // Channel flip-flops: the A-channel valid and the D-channel ready. Both are reset asynchronously
  // to zero; reg_d_ready then becomes 1 at the first clock edge after reset release.
  // REQ: BR-3-21, BR-3-22, BR-3-31, BR-20-11
  always_ff @(posedge i_clk_core, negedge i_rst_n_core) begin : p_ff_chan_ctrl
    if (!i_rst_n_core) begin
      reg_a_valid <= 1'b0;
      reg_d_ready <= 1'b0;
    end else begin
      reg_a_valid <= w_a_valid_nxt;
      reg_d_ready <= 1'b1;
    end
  end

  // Payload flip-flops: direction, address and data of the request. They are also reset to zero so
  // the channel A outputs are defined after reset; the device ignores them while a_valid is low.
  // REQ: BR-7.3-02, BR-7.3-03, BR-14.1-03
  always_ff @(posedge i_clk_core, negedge i_rst_n_core) begin : p_ff_payload
    if (!i_rst_n_core) begin
      reg_a_rd   <= 1'b0;
      reg_a_addr <= '0;
      reg_a_data <= '0;
    end else begin
      reg_a_rd   <= w_a_rd_nxt;
      reg_a_addr <= w_a_addr_nxt;
      reg_a_data <= w_a_data_nxt;
    end
  end

endmodule

/*
 * Project      : VLSI Technology - AI RTL generator
 * Author       : Nguyen Quan and Claude (user)
 * AI Flow      : VLSIT RTL Generator AI Automation Flow
 * AI Flow Page : https://github.com/nguyenquanicd/VLSIT_RTL_Generator_AI_Model
 * Date         : 2026-10-18
 * Module       : m_apb_tlul_bridge
 * Purpose      : Structural top of the APB4 to TL-UL bridge: an APB4 completer on one side and a
 *                TL-UL host on the other, in one clock domain; changing outputs come from flops.
 * Spec sections: 1.1 (overview), 5.1 (internal interface), 6.2 (ports), 7 (clock and reset),
 *                8 (parameters), 14.2 (hierarchy).
 */
`timescale 1ns/1ps

// REQ: BR-14.2-01, BR-3-23, BR-3-15, BR-3-16, BR-3-29
module m_apb_tlul_bridge #(
  // Parameter Description: width of the byte address on both buses.
  // Parameter values: legal range is 16 to 32; default is 32.
  // Parameter unit: bit
  parameter logic [31:0] PARA_ADDR_W = 32,
  // Parameter Description: width of the TL-UL source identifier on channels A and D.
  // Parameter values: legal range is 1 to 8; default is 8.
  // Parameter unit: bit
  parameter logic [31:0] PARA_SRC_W = 8,
  // Parameter Description: constant source identifier of every request; it fits PARA_SRC_W bits.
  // Parameter values: 0 to 2^PARA_SRC_W - 1; default is 0.
  // Parameter unit: none
  parameter logic [31:0] PARA_SRC_ID = 0,
  // Parameter Description: width of the a_user bits, which are always driven to zero.
  // Parameter values: legal range is 1 to 32; default is 1.
  // Parameter unit: bit
  parameter logic [31:0] PARA_A_USER_W = 1,
  // Parameter Description: width of the unused d_sink input; it has no effect on behavior.
  // Parameter values: legal range is 1 to 4; default is 1.
  // Parameter unit: bit
  parameter logic [31:0] PARA_D_SINK_W = 1,
  // Parameter Description: width of the unused d_user input; it has no effect on behavior.
  // Parameter values: legal range is 1 to 32; default is 1.
  // Parameter unit: bit
  parameter logic [31:0] PARA_D_USER_W = 1
) (
  input wire i_clk_core,
  input wire i_rst_n_core,
  input wire i_apb_psel,
  input wire i_apb_penable,
  input wire i_apb_pwrite,
  input wire i_tlul_a_ready,
  input wire i_tlul_d_valid,
  input wire i_tlul_d_error,
  input wire [PARA_ADDR_W-1:0] i_apb_paddr,
  // WAIVER: PPROT is accepted and ignored by the bridge (DEC-007), so the input is unused.
  // verilator lint_off UNUSEDSIGNAL
  input wire [2:0] i_apb_pprot,
  // verilator lint_on UNUSEDSIGNAL
  input wire [3:0] i_apb_pstrb,
  input wire [31:0] i_apb_pwdata,
  input wire [2:0] i_tlul_d_opcode,
  // WAIVER: d_param and d_size are present as ports but unused by the response check (DEC-006).
  // verilator lint_off UNUSEDSIGNAL
  input wire [2:0] i_tlul_d_param,
  input wire [1:0] i_tlul_d_size,
  // verilator lint_on UNUSEDSIGNAL
  input wire [PARA_SRC_W-1:0] i_tlul_d_source,
  // WAIVER: d_sink is present as a port but has no behavioral effect (DEC-006).
  // verilator lint_off UNUSEDSIGNAL
  input wire [PARA_D_SINK_W-1:0] i_tlul_d_sink,
  // verilator lint_on UNUSEDSIGNAL
  input wire [31:0] i_tlul_d_data,
  // WAIVER: d_user is present as a port but has no behavioral effect (DEC-006).
  // verilator lint_off UNUSEDSIGNAL
  input wire [PARA_D_USER_W-1:0] i_tlul_d_user,
  // verilator lint_on UNUSEDSIGNAL
  output logic o_apb_pready,
  output logic o_apb_pslverr,
  output logic o_tlul_a_valid,
  output logic o_tlul_d_ready,
  output logic [31:0] o_apb_prdata,
  output logic [2:0] o_tlul_a_opcode,
  output logic [2:0] o_tlul_a_param,
  output logic [1:0] o_tlul_a_size,
  output logic [PARA_SRC_W-1:0] o_tlul_a_source,
  output logic [PARA_ADDR_W-1:0] o_tlul_a_address,
  output logic [3:0] o_tlul_a_mask,
  output logic [31:0] o_tlul_a_data,
  output logic [PARA_A_USER_W-1:0] o_tlul_a_user
);

  // Interconnect between the APB side and the TL-UL side: a request bundle and a response bundle.
  // The inputs i_apb_pprot, i_tlul_d_param, i_tlul_d_size, i_tlul_d_sink and i_tlul_d_user are
  // present for integration only and are not used (PPROT is ignored; the response check does not
  // use d_size, d_param, d_sink or d_user).
  // REQ: BR-2.3-03, BR-8-06, BR-8-07
  logic w_req_launch;
  logic w_req_wr;
  logic w_resp_valid;
  logic w_resp_err;
  logic [PARA_ADDR_W-3:0] w_req_addr;
  logic [31:0] w_req_wdata;
  logic [31:0] w_resp_rdata;

  // APB side: detects the Setup phase, checks and launches the request, returns the completion.
  // REQ: BR-14.2-02, BR-14.2-04
  m_apb_if #(
    .PARA_ADDR_W (PARA_ADDR_W)
  ) u_apb_if (
    .i_clk_core    (i_clk_core),
    .i_rst_n_core  (i_rst_n_core),
    .i_apb_psel    (i_apb_psel),
    .i_apb_penable (i_apb_penable),
    .i_apb_pwrite  (i_apb_pwrite),
    .i_resp_valid  (w_resp_valid),
    .i_resp_err    (w_resp_err),
    .i_apb_paddr   (i_apb_paddr),
    .i_apb_pstrb   (i_apb_pstrb),
    .i_apb_pwdata  (i_apb_pwdata),
    .i_resp_rdata  (w_resp_rdata),
    .o_req_launch  (w_req_launch),
    .o_req_wr      (w_req_wr),
    .o_apb_pready  (o_apb_pready),
    .o_apb_pslverr (o_apb_pslverr),
    .o_req_addr    (w_req_addr),
    .o_req_wdata   (w_req_wdata),
    .o_apb_prdata  (o_apb_prdata)
  );

  // TL-UL side: drives channel A from flops, accepts and checks the response, reports it upward.
  // REQ: BR-14.2-03, BR-14.2-04
  m_tlul_if #(
    .PARA_ADDR_W   (PARA_ADDR_W),
    .PARA_SRC_W    (PARA_SRC_W),
    .PARA_SRC_ID   (PARA_SRC_ID),
    .PARA_A_USER_W (PARA_A_USER_W)
  ) u_tlul_if (
    .i_clk_core       (i_clk_core),
    .i_rst_n_core     (i_rst_n_core),
    .i_req_launch     (w_req_launch),
    .i_req_wr         (w_req_wr),
    .i_tlul_a_ready   (i_tlul_a_ready),
    .i_tlul_d_valid   (i_tlul_d_valid),
    .i_tlul_d_error   (i_tlul_d_error),
    .i_req_addr       (w_req_addr),
    .i_req_wdata      (w_req_wdata),
    .i_tlul_d_opcode  (i_tlul_d_opcode),
    .i_tlul_d_source  (i_tlul_d_source),
    .i_tlul_d_data    (i_tlul_d_data),
    .o_resp_valid     (w_resp_valid),
    .o_resp_err       (w_resp_err),
    .o_tlul_a_valid   (o_tlul_a_valid),
    .o_tlul_d_ready   (o_tlul_d_ready),
    .o_resp_rdata     (w_resp_rdata),
    .o_tlul_a_opcode  (o_tlul_a_opcode),
    .o_tlul_a_param   (o_tlul_a_param),
    .o_tlul_a_size    (o_tlul_a_size),
    .o_tlul_a_source  (o_tlul_a_source),
    .o_tlul_a_address (o_tlul_a_address),
    .o_tlul_a_mask    (o_tlul_a_mask),
    .o_tlul_a_data    (o_tlul_a_data),
    .o_tlul_a_user    (o_tlul_a_user)
  );

endmodule
